
let currentWallet = null;
let priceChart;
let chartData = {
  labels: [],
  datasets: [{
    label: 'CAP/NATIVE Price',
    data: [],
    borderColor: 'blue',
    fill: false,
    tension: 0.1
  }]
};

async function fetchWallets() {
  const res = await fetch('/api/wallets');
  const wallets = await res.json();
  const walletSelect = document.getElementById('walletSelect');
  const walletList = document.getElementById('walletList');
  walletSelect.innerHTML = '';
  walletList.innerHTML = '';

  wallets.forEach(w => {
    const option = document.createElement('option');
    option.value = w.address;
    option.text = w.address.slice(0, 10) + '...';
    walletSelect.appendChild(option);

    const li = document.createElement('li');
    li.className = 'list-group-item';
    li.textContent = w.address;
    walletList.appendChild(li);
  });

  currentWallet = (wallets.length > 0) ? wallets[0].address : null;
  walletSelect.value = currentWallet;
  walletSelect.onchange = () => {
    currentWallet = walletSelect.value;
    updateWalletInfo();
  };
  updateWalletInfo();
}

async function updateWalletInfo() {
  if (!currentWallet) return;
  const res = await fetch('/api/wallet-info?address=' + currentWallet);
  const info = await res.json();
  document.getElementById('wallet-address').innerText = info.address;
  document.getElementById('wallet-cap').innerText = info.capTokenBalance;
  document.getElementById('wallet-native').innerText = info.balance;
}

async function handleSwap() {
  const inputAmount = parseFloat(document.getElementById('inputAmount').value);
  const inputSymbol = document.getElementById('inputSymbol').value;
  const res = await fetch('/api/swap', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ inputAmount, inputSymbol, senderAddress: currentWallet })
  });
  const data = await res.json();
  if (data.type === 'success') {
    document.getElementById('swapResult').innerText = data.swapTx.outputAmount + ' ' + data.swapTx.outputSymbol;
    updateWalletInfo();
  } else {
    document.getElementById('swapResult').innerText = 'Swap failed: ' + data.message;
  }
}

async function updateLiquidityStats() {
  const res = await fetch('/api/liquidity-stats');
  const stats = await res.json();
  document.getElementById('reserve-cap').innerText = stats.reserveCAP;
  document.getElementById('reserve-native').innerText = stats.reserveNATIVE;
  document.getElementById('pool-share').innerText = stats.totalShares;
  const price = stats.reserveNATIVE / stats.reserveCAP;
  document.getElementById('cap-price').innerText = price.toFixed(4);
  updateChart(price);
}

function updateChart(price) {
  const now = new Date().toLocaleTimeString();
  chartData.labels.push(now);
  chartData.datasets[0].data.push(price);
  if (chartData.labels.length > 20) {
    chartData.labels.shift();
    chartData.datasets[0].data.shift();
  }
  if (!priceChart) {
    const ctx = document.getElementById('priceChart').getContext('2d');
    priceChart = new Chart(ctx, { type: 'line', data: chartData });
  } else {
    priceChart.update();
  }
}

async function generateNewWallet() {
  const res = await fetch('/api/generate-wallet', { method: 'POST' });
  const wallet = await res.json();
  alert('New wallet created: ' + wallet.address);
  fetchWallets();
}

setInterval(updateLiquidityStats, 5000);
fetchWallets();
updateLiquidityStats();
